CREATE VIEW h1_eq_wh.substance__active_moiety AS
SELECT (SELECT k.UNII_CD FROM wh.T_SUBST_MSTR k WHERE k.SUBST_SK = w.SUBST_SK LIMIT 1) AS owner__unii, (SELECT k.UNII_CD FROM wh.T_SUBST_MSTR k WHERE k.SUBST_SK = w.MOIETY_SUBST_SK LIMIT 1) AS moiety__unii, w.SRC_TXT AS source FROM wh.X_SALT_MOIETY w;
CREATE VIEW h1_eq_h2.substance__active_moiety AS
