CREATE VIEW h1_eq_wh.organization__aliases AS
SELECT (SELECT k.ORG_CD FROM wh.T_ORG_MSTR k WHERE k.ORG_SK = w.ORG_SK LIMIT 1) AS owner__slug, w.ALIAS_NM AS name, (SELECT r.CD_DSC FROM wh.T_REF_CD r WHERE r.CD_DOM = 'ALIAS_SRC' AND r.CD_VAL = w.SRC_CD) AS source, w.EVID_TXT AS evidence FROM wh.X_ORG_ALIAS w;
CREATE VIEW h1_eq_h2.organization__aliases AS
