CREATE VIEW h1_eq_wh.clinical_drug AS
SELECT w.RXCUI AS rxcui, w.CLIN_DRG_NM AS name, w.TTY_CD AS term_type FROM wh.T_CLIN_DRG w;
CREATE VIEW h1_eq_h2.clinical_drug AS
SELECT c.rxcui AS rxcui, c.name AS name, c.term_type AS term_type FROM h2.clinical_drug c;

CREATE VIEW h1_eq_wh.clinical_drug__generic AS
SELECT (SELECT k.RXCUI FROM wh.T_CLIN_DRG k WHERE k.CLIN_DRG_SK = w.BRND_CLIN_DRG_SK LIMIT 1) AS owner__rxcui, (SELECT k.RXCUI FROM wh.T_CLIN_DRG k WHERE k.CLIN_DRG_SK = w.GNRC_CLIN_DRG_SK LIMIT 1) AS drug__rxcui, w.SRC_TXT AS source FROM wh.X_BRND_GNRC w;
CREATE VIEW h1_eq_h2.clinical_drug__generic AS
SELECT (SELECT k.rxcui FROM h2.clinical_drug k WHERE k.iri = x.owner_iri) AS owner__rxcui, (SELECT k.rxcui FROM h2.clinical_drug k WHERE k.iri = x.drug_iri) AS drug__rxcui, x.source AS source FROM h2.clinical_drug__generic x;

CREATE VIEW h1_eq_wh.product AS
SELECT w.PRD_CD AS product_ndc, w.PRD_NM AS name, (SELECT r.CD_DSC FROM wh.T_REF_CD r WHERE r.CD_DOM = 'DSG_FRM' AND r.CD_VAL = w.DSG_FRM_CD) AS dosage_form, (SELECT r.CD_DSC FROM wh.T_REF_CD r WHERE r.CD_DOM = 'PRD_TYP' AND r.CD_VAL = w.PRD_TYP_CD) AS product_type, (w.FNSHD_FLG = 'Y') AS finished, (SELECT coalesce(array_agg(u ORDER BY u COLLATE "C"), '{}') FROM unnest(ARRAY(SELECT (SELECT r.CD_DSC FROM wh.T_REF_CD r WHERE r.CD_DOM = 'RTE' AND r.CD_VAL = e.RTE_CD) FROM wh.T_PRD_RTE e WHERE e.PRD_SK = w.PRD_SK)) AS u) AS routes, (SELECT k.RXCUI FROM wh.T_CLIN_DRG k WHERE k.CLIN_DRG_SK = w.RXN_CLIN_DRG_SK LIMIT 1) AS clinical_drug__rxcui FROM wh.T_PRD_MSTR w;
CREATE VIEW h1_eq_h2.product AS
SELECT c.product_ndc AS product_ndc, c.name AS name, c.dosage_form AS dosage_form, c.product_type AS product_type, c.finished AS finished, (SELECT coalesce(array_agg(u ORDER BY u COLLATE "C"), '{}') FROM unnest(c.routes) AS u) AS routes, (SELECT k.rxcui FROM h2.clinical_drug k WHERE k.iri = c.clinical_drug_iri) AS clinical_drug__rxcui FROM h2.product c;

CREATE VIEW h1_eq_wh.product__ingredients AS
SELECT (SELECT k.PRD_CD FROM wh.T_PRD_MSTR k WHERE k.PRD_SK = w.PRD_SK LIMIT 1) AS owner__product_ndc, w.INGR_SEQ - 1 AS position, (SELECT k.UNII_CD FROM wh.T_SUBST_MSTR k WHERE k.SUBST_SK = w.SUBST_SK LIMIT 1) AS substance__unii, w.STRNTH_VAL AS strength_value, w.STRNTH_UOM AS strength_unit FROM wh.T_PRD_INGR w;
CREATE VIEW h1_eq_h2.product__ingredients AS
SELECT (SELECT k.product_ndc FROM h2.product k WHERE k.iri = x.owner_iri) AS owner__product_ndc, x.position AS position, (SELECT k.unii FROM h2.substance k WHERE k.iri = x.substance_iri) AS substance__unii, x.strength_value AS strength_value, x.strength_unit AS strength_unit FROM h2.product__ingredients x;

CREATE VIEW h1_eq_wh.product__drug_mappings AS
SELECT (SELECT k.PRD_CD FROM wh.T_PRD_MSTR k WHERE k.PRD_SK = w.PRD_SK LIMIT 1) AS owner__product_ndc, w.MAP_SEQ - 1 AS position, (SELECT k.RXCUI FROM wh.T_CLIN_DRG k WHERE k.CLIN_DRG_SK = w.CLIN_DRG_SK LIMIT 1) AS clinical_drug__rxcui, (SELECT r.CD_DSC FROM wh.T_REF_CD r WHERE r.CD_DOM = 'MAP_SRC' AND r.CD_VAL = w.SRC_CD) AS source, w.EVID_TXT AS evidence FROM wh.X_NDC_RXN w;
CREATE VIEW h1_eq_h2.product__drug_mappings AS
SELECT (SELECT k.product_ndc FROM h2.product k WHERE k.iri = x.owner_iri) AS owner__product_ndc, x.position AS position, (SELECT k.rxcui FROM h2.clinical_drug k WHERE k.iri = x.clinical_drug_iri) AS clinical_drug__rxcui, x.source AS source, x.evidence AS evidence FROM h2.product__drug_mappings x;

CREATE VIEW h1_eq_wh.packaged_product AS
SELECT w.PKG_NDC AS ndc, (SELECT k.PRD_CD FROM wh.T_PRD_MSTR k WHERE k.PRD_SK = w.PRD_SK LIMIT 1) AS product__product_ndc, (SELECT k.ORG_CD FROM wh.T_ORG_MSTR k WHERE k.ORG_SK = w.LBLR_ORG_SK LIMIT 1) AS labeler__slug, w.PKG_DESC AS description, w.PKG_NDC11 AS ndc11 FROM wh.T_PKG w;
CREATE VIEW h1_eq_h2.packaged_product AS
