CREATE VIEW h1_eq_wh.adverse_event_report AS
SELECT w.RPT_ID AS report_id, (SELECT r.CD_DSC FROM wh.T_REF_CD r WHERE r.CD_DOM = 'SRC_SYS' AND r.CD_VAL = w.SRC_SYS_CD) AS source_system, to_date(w.RCPT_DT::text, 'YYYYMMDD') AS receipt_date, (w.SRS_FLG = 'Y') AS serious, (SELECT coalesce(array_agg(u ORDER BY u COLLATE "C"), '{}') FROM unnest(array_remove(ARRAY[CASE WHEN w.SRS_DTH_FLG = 'Y' THEN 'death' END, CASE WHEN w.SRS_LT_FLG = 'Y' THEN 'life threatening' END, CASE WHEN w.SRS_HOSP_FLG = 'Y' THEN 'hospitalization' END, CASE WHEN w.SRS_DSBL_FLG = 'Y' THEN 'disabling' END, CASE WHEN w.SRS_CA_FLG = 'Y' THEN 'congenital anomaly' END, CASE WHEN w.SRS_OTH_FLG = 'Y' THEN 'other' END]::text[], NULL)) AS u) AS seriousness_criteria, w.PT_AGE_YRS AS patient_age_years FROM wh.T_AE_HDR w;
CREATE VIEW h1_eq_h2.adverse_event_report AS
SELECT c.report_id AS report_id, c.source_system AS source_system, c.receipt_date AS receipt_date, c.serious AS serious, (SELECT coalesce(array_agg(u ORDER BY u COLLATE "C"), '{}') FROM unnest(c.seriousness_criteria) AS u) AS seriousness_criteria, c.patient_age_years AS patient_age_years FROM h2.adverse_event_report c;

CREATE VIEW h1_eq_wh.adverse_event_report__drugs AS
SELECT (SELECT k.RPT_ID FROM wh.T_AE_HDR k WHERE k.AE_SK = w.AE_SK LIMIT 1) AS owner__report_id, w.DRG_SEQ - 1 AS position, w.DRG_NM AS drug_name, (SELECT k.RXCUI FROM wh.T_CLIN_DRG k WHERE k.CLIN_DRG_SK = w.CLIN_DRG_SK LIMIT 1) AS clinical_drug__rxcui, (SELECT r.CD_DSC FROM wh.T_REF_CD r WHERE r.CD_DOM = 'DRG_ROLE' AND r.CD_VAL = w.DRG_ROLE_CD) AS role FROM wh.T_AE_DRG w;
CREATE VIEW h1_eq_h2.adverse_event_report__drugs AS
SELECT (SELECT k.report_id FROM h2.adverse_event_report k WHERE k.iri = x.owner_iri) AS owner__report_id, x.position AS position, x.drug_name AS drug_name, (SELECT k.rxcui FROM h2.clinical_drug k WHERE k.iri = x.clinical_drug_iri) AS clinical_drug__rxcui, x.role AS role FROM h2.adverse_event_report__drugs x;

CREATE VIEW h1_eq_wh.adverse_event_report__reactions AS
SELECT (SELECT k.RPT_ID FROM wh.T_AE_HDR k WHERE k.AE_SK = w.AE_SK LIMIT 1) AS owner__report_id, w.RXN_SEQ - 1 AS position, w.RXN_TRM AS term FROM wh.T_AE_RXN w;
CREATE VIEW h1_eq_h2.adverse_event_report__reactions AS
SELECT (SELECT k.report_id FROM h2.adverse_event_report k WHERE k.iri = x.owner_iri) AS owner__report_id, x.position AS position, x.term AS term FROM h2.adverse_event_report__reactions x;

CREATE VIEW h1_eq_wh.recall AS
SELECT DISTINCT w.RCL_NO AS recall_number, CASE w.RCL_CLS_CD WHEN '1' THEN 'I' WHEN '2' THEN 'II' WHEN '3' THEN 'III' END AS classification, w.RCL_RSN_TXT AS reason, to_date(w.RPT_DT::text, 'YYYYMMDD') AS report_date, (SELECT k.ORG_CD FROM wh.T_ORG_MSTR k WHERE k.ORG_SK = w.FIRM_ORG_SK LIMIT 1) AS recalling_firm__slug FROM wh.T_RCL_PRD_DNRM w;
CREATE VIEW h1_eq_h2.recall AS
SELECT c.recall_number AS recall_number, c.classification AS classification, c.reason AS reason, c.report_date AS report_date, (SELECT k.slug FROM h2.organization k WHERE k.iri = c.recalling_firm_iri) AS recalling_firm__slug FROM h2.recall c;

CREATE VIEW h1_eq_wh.recall__products AS
SELECT DISTINCT (SELECT k.RCL_NO FROM wh.T_RCL_PRD_DNRM k WHERE k.RCL_SK = w.RCL_SK LIMIT 1) AS owner__recall_number, (SELECT k.PRD_CD FROM wh.T_PRD_MSTR k WHERE k.PRD_SK = w.PRD_SK LIMIT 1) AS target__product_ndc FROM wh.T_RCL_PRD_DNRM w WHERE w.PRD_SK IS NOT NULL;
CREATE VIEW h1_eq_h2.recall__products AS
SELECT (SELECT k.recall_number FROM h2.recall k WHERE k.iri = b.owner_iri) AS owner__recall_number, (SELECT k.product_ndc FROM h2.product k WHERE k.iri = b.target_iri) AS target__product_ndc FROM h2.recall__products b;

CREATE VIEW h1_eq_wh.adverse_event_report__drugs__harmonized_clinical_drugs AS
SELECT (SELECT k.RPT_ID FROM wh.T_AE_HDR k WHERE k.AE_SK = w.AE_SK LIMIT 1) AS owner__report_id, w.DRG_SEQ - 1 AS position, (SELECT k.RXCUI FROM wh.T_CLIN_DRG k WHERE k.CLIN_DRG_SK = w.CLIN_DRG_SK LIMIT 1) AS target__rxcui FROM wh.X_AE_DRG_RXN w;
CREATE VIEW h1_eq_h2.adverse_event_report__drugs__harmonized_clinical_drugs AS
SELECT (SELECT k.report_id FROM h2.adverse_event_report k WHERE k.iri = d.owner_iri) AS owner__report_id, d.position AS position, (SELECT k.rxcui FROM h2.clinical_drug k WHERE k.iri = b.target_iri) AS target__rxcui FROM h2.adverse_event_report__drugs__harmonized_clinical_drugs b JOIN h2.adverse_event_report__drugs d ON d.iri = b.owner_iri;
